152	function buildRunBadges(item, isActive) {
153	  var badges = '';
154	  if (isActive) {
155	    badges += '<span class="badge badge-in-progress">Running</span>';
156	  }
157	  if (item && item.is_dry_run) {
158	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
