163	/* ----------------------------------------------------------
164	   Orchestrator Toolbar
165	   Renders Kill + Resume buttons into toolbarEl.
166	   Always visible; buttons are disabled (with explanatory
167	   tooltips) when the corresponding action is unavailable.
168	
169	   opts: {
170	     loading:        bool,           — show "Loading…" disabled state
171	     hasActiveRun:   bool,           — is there an active run?
172	     queueEntry:     object|null,    — matching queue entry (kill)
173	     runMeta:        object|null,    — run metadata (resume)
174	     meta:           object,         — project meta (plan_path, status)
175	     repo:           string,
176	     slug:           string,
177	     app:            Element,        — root element (re-render after resume)
178	     onKillDone:     Function,       — called after a successful kill
179	     pollController: object|null,    — owning pollController from renderProjectDetail
180	   }
181	   ---------------------------------------------------------- */
182	function renderOrchToolbar(toolbarEl, opts) {
183	  if (!toolbarEl) return;
184	  toolbarEl.innerHTML = '';
185	
186	  var loading         = !!opts.loading;
187	  var hasActiveRun    = !!opts.hasActiveRun;
188	  var queueEntry      = opts.queueEntry      || null;
189	  var runMeta         = opts.runMeta         || null;
190	  var meta            = opts.meta            || {};
191	  var repo            = opts.repo            || '';
192	  var slug            = opts.slug            || '';
193	  var app             = opts.app             || null;
194	  var onKillDone      = typeof opts.onKillDone === 'function' ? opts.onKillDone : null;
195	  var pollController  = opts.pollController  || null;
196	
197	  // ── Kill button ─────────────────────────────────────────────────────
198	  var killDisabled = true;
199	  var killTitle    = 'Loading\u2026';
200	  if (!loading) {
201	    if (!hasActiveRun) {
202	      killTitle = 'No active run to kill';
203	    } else if (!queueEntry) {
204	      killTitle = 'Run is active but not found in the queue \u2014 use: node scripts/kill-orchestrator.js --force';
205	    } else {
206	      killDisabled = false;
207	      killTitle    = '';
208	    }
209	  }
210	
211	  if (killDisabled) {
212	    var killBtn = document.createElement('button');
213	    killBtn.type = 'button';
214	    killBtn.className = 'btn btn-danger btn-sm orchestrator-kill-btn';
215	    killBtn.textContent = 'Kill';
216	    killBtn.disabled = true;
217	    if (killTitle) killBtn.title = killTitle;
218	    toolbarEl.appendChild(killBtn);
219	  } else {
220	    toolbarEl.appendChild(
221	      OrchestratorWidgets.renderKillButton(queueEntry.id, function () {
222	        if (onKillDone) onKillDone();
223	      })
224	    );
225	  }
226	
227	  // ── Resume button ────────────────────────────────────────────────────
228	  var resumeDisabled = true;
229	  var resumeTitle    = 'Loading\u2026';
230	  if (!loading) {
231	    if (hasActiveRun) {
232	      resumeTitle = 'Cannot resume while a run is active';
233	    } else if (!meta.plan_path) {
234	      resumeTitle = 'No plan path configured for this project';
235	    } else if (meta.status === 'COMPLETE') {
236	      resumeTitle = 'Project is already complete \u2014 nothing to resume';
237	    } else if (meta.status === 'ARCHIVED') {
238	      resumeTitle = 'Project is archived';
239	    } else if (!runMeta || !runMeta.thread_id) {
240	      resumeTitle = 'No interrupted run found';
241	    } else if (runMeta.dry_run === true) {
242	      resumeTitle = 'Dry runs cannot be resumed';
243	    } else if (runMeta.result === 'SUCCESS') {
244	      resumeTitle = 'Last run completed successfully \u2014 nothing to resume';
245	    } else {
246	      resumeDisabled = false;
247	      resumeTitle    = '';
248	    }
249	  }

251	  var resumeBtn = document.createElement('button');
252	  resumeBtn.id   = 'orch-resume-btn';
253	  resumeBtn.type = 'button';
254	  resumeBtn.className = 'btn btn-resume btn-sm';
255	  resumeBtn.textContent = 'Resume';
256	  resumeBtn.disabled = resumeDisabled;
257	  if (resumeTitle) resumeBtn.title = resumeTitle;
258	
259	  if (!resumeDisabled) {
260	    var threadId = runMeta.thread_id;
261	    var planPath = meta.plan_path;
262	
263	    resumeBtn.addEventListener('click', function () {
264	      resumeBtn.disabled = true;
265	      resumeBtn.textContent = 'Resuming\u2026';
266	      // Remove any stale error banner.
267	      var prevErr = document.getElementById('orch-resume-error');
268	      if (prevErr) prevErr.remove();
269	
270	      API.orchestratorStart(planPath, false, threadId).then(function (result) {
271	        if (result && result.started) {
272	          resumeBtn.textContent = 'Launching\u2026';
273	          var pollResume = function () {
274	            API.orchestratorGetQueue().then(function (queue) {
275	              var hasActiveEntry = Array.isArray(queue) && queue.some(function (entry) {
276	                return entry && (entry.effectiveStatus === 'pending' ||
277	                                 entry.effectiveStatus === 'started');
278	              });
279	              if (hasActiveEntry) {
280	                // Settle the resume poll: the run is now active, so hand back
281	                // to the combined poll (or trigger a full re-render if no
282	                // pollController is present — legacy fallback).
283	                if (pollController) {
284	                  pollController.settleResumePolling({ app: app, repo: repo, slug: slug });
285	                } else {
286	                  Router._clearPolling();
287	                  if (app) renderProjectDetail(app, repo, slug);
288	                }
289	              }
290	            }).catch(function () { /* keep polling */ });
291	          };
292	          // Switch to resume mode: clears combined interval, starts 3s resume poll.
293	          if (pollController) {
294	            pollController.startResumePolling({ pollFn: pollResume });
295	          } else {
296	            Router._setPolling(pollResume, 3000);
297	          }
298	        } else {
299	          resumeBtn.disabled = false;
300	          resumeBtn.textContent = 'Resume';
301	          var errEl = document.getElementById('orch-resume-error');
302	          if (!errEl) {
303	            errEl = document.createElement('p');
304	            errEl.id = 'orch-resume-error';
305	            errEl.className = 'error-banner';
306	            toolbarEl.insertAdjacentElement('afterend', errEl);
307	          }
308	          errEl.textContent = 'Resume could not be started.';
309	        }
310	      }).catch(function (err) {
311	        resumeBtn.disabled = false;
312	        resumeBtn.textContent = 'Resume';
313	        var errEl = document.getElementById('orch-resume-error');
314	        if (!errEl) {
315	          errEl = document.createElement('p');
316	          errEl.id = 'orch-resume-error';
317	          errEl.className = 'error-banner';
318	          toolbarEl.insertAdjacentElement('afterend', errEl);
319	        }
320	        errEl.textContent = 'Resume failed: ' + (err.message || String(err));
321	      });
322	    });
323	  }
324	
325	  toolbarEl.appendChild(resumeBtn);
326	}
