504	/* ----------------------------------------------------------
505	   4c-iii. State Snapshot & Diff Helpers
506	   Pure functions — no DOM access, JSON-serializable outputs.
507	   Used by WP-003 polling to decide patch vs. full re-render.
508	   ---------------------------------------------------------- */
509	
510	/**
511	 * Extract a comparable state snapshot from API response objects.
512	 *
513	 * @param {object} project      - Response from API.getProject()
514	 * @param {Array|null} overviewResult - Response from API.getWorkPackageOverview() (may be null)
515	 * @returns {{
516	 *   status: string,
517	 *   last_updated: string,
518	 *   synthesis_generated: boolean,
519	 *   wpStatuses: Object.<string, { status: string, pipelineStages: Array }>,
520	 *   health: null | { work_packages_needing_reset: number }
521	 * }}
522	 */
523	function _snapshotProjectState(project, overviewResult) {
524	  var meta = (project && project.meta) || {};
525	  var wps  = (project && project.work_packages) || [];
526	
527	  // Build per-WP status map
528	  var wpStatuses = {};
529	  wps.forEach(function (wp) {
530	    if (!wp || !wp.work_package_id) return;
531	    wpStatuses[wp.work_package_id] = {
532	      status: wp.status || '',
533	      pipelineStages: [],
534	    };
535	  });
536	
537	  // Enrich with pipeline stage data from overview
538	  if (Array.isArray(overviewResult)) {
539	    overviewResult.forEach(function (entry) {
540	      if (!entry || !entry.work_package_id) return;
541	      var id = entry.work_package_id;
542	      var stages = Array.isArray(entry.pipeline_stages)
543	        ? entry.pipeline_stages.map(function (s) {
544	            return {
545	              type:         s.type        || '',
546	              status:       s.status      || '',
547	              agent:        s.agent       || '',
548	              rework_count: s.rework_count || 0,
549	            };
550	          })

551	        : [];
552	      if (wpStatuses[id]) {
553	        wpStatuses[id].pipelineStages = stages;
554	      } else {
555	        // Overview entry present without a matching WP in the main list.
556	        wpStatuses[id] = { status: '', pipelineStages: stages };
557	      }
558	    });
559	  }
560	
561	  return {
562	    status:               meta.status              || '',
563	    last_updated:         meta.last_updated         || '',
564	    synthesis_generated:  !!(project && project.synthesis_generated),
565	    wpStatuses:           wpStatuses,
566	    health:               null,  // populated asynchronously via getProjectHealth()
567	  };
568	}
569	
570	/**
571	 * Compare two project-state snapshots and classify the difference.
572	 *
573	 * Structural changes (require full re-render):
574	 *   - The number of work packages differs between snapshots.
575	 *   - The project transitioned to COMPLETE or ARCHIVED status.
576	 *
577	 * Data-only changes (patchable in-place):
578	 *   - Status badge changed but is not a structural transition.
579	 *   - Any per-WP status or pipeline-stage changed.
580	 *   - synthesis_generated flipped.
581	 *   - health changed (including null → value transitions).
582	 *   - last_updated changed.
583	 *
584	 * NOTE — per-WP iteration order: per-WP status/pipeline changes are detected by
585	 * iterating over `next.wpStatuses` keys only. A WP present in `prev` but absent
586	 * from `next` is therefore not tracked per-field; the structural `wpCount` check
587	 * handles that case before per-WP diffing is reached. In practice, a missing WP
588	 * always triggers a structural re-render, so the per-field gap is intentional.
589	 *
590	 * @param {object} prev - Previous snapshot from _snapshotProjectState().
591	 *   Must be non-null; passing null will throw on Object.keys(prev.wpStatuses).
592	 *   Callers must initialise pollStateRef[0] with a real snapshot before
593	 *   registering the poll interval — the 5s setInterval delay ensures the
594	 *   first tick cannot fire before that assignment completes.
595	 * @param {object} next - Current  snapshot from _snapshotProjectState().
596	 * @returns {{ type: 'none'|'data'|'structural', changes: object }}
597	 */
598	function _diffProjectState(prev, next) {
599	  var changes = {};
600	  var changeType = 'none';
601	
602	  function markData(key, from, to) {
603	    changes[key] = { from: from, to: to };
604	    if (changeType === 'none') changeType = 'data';
605	  }
606	
607	  function markStructural(key, from, to) {
608	    changes[key] = { from: from, to: to };
609	    changeType = 'structural';
610	  }
611	
612	  // ── WP count ────────────────────────────────────────────────────────
613	  var prevIds = Object.keys(prev.wpStatuses || {});
614	  var nextIds = Object.keys(next.wpStatuses || {});
615	  if (prevIds.length !== nextIds.length) {
616	    markStructural('wpCount', prevIds.length, nextIds.length);
617	  }
618	
619	  // ── Project status ──────────────────────────────────────────────────
620	  if (prev.status !== next.status) {
621	    var isStructuralStatus = next.status === 'COMPLETE' || next.status === 'ARCHIVED';
622	    if (isStructuralStatus) {
623	      markStructural('status', prev.status, next.status);
624	    } else {
625	      markData('status', prev.status, next.status);
626	    }
627	  }
628	
629	  // ── Per-WP statuses and pipeline stages ─────────────────────────────
630	  nextIds.forEach(function (id) {
631	    var prevWp = (prev.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
632	    var nextWp = (next.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
633	
634	    if (prevWp.status !== nextWp.status) {
635	      markData('wp.' + id + '.status', prevWp.status, nextWp.status);
636	    }
637	
638	    // Compare pipeline stages as JSON strings (simple deep-equal for flat objects)
639	    var prevStagesStr = JSON.stringify(prevWp.pipelineStages || []);
640	    var nextStagesStr = JSON.stringify(nextWp.pipelineStages || []);
641	    if (prevStagesStr !== nextStagesStr) {
642	      markData('wp.' + id + '.pipelineStages', prevWp.pipelineStages, nextWp.pipelineStages);
643	    }
644	  });
645	
646	  // ── synthesis_generated ─────────────────────────────────────────────
647	  if (!!prev.synthesis_generated !== !!next.synthesis_generated) {
648	    markData('synthesis_generated', prev.synthesis_generated, next.synthesis_generated);
649	  }
650	
651	  // ── health ──────────────────────────────────────────────────────────
652	  // null-to-value (or any value change) is data-only
653	  var prevHealthStr = JSON.stringify(prev.health || null);
654	  var nextHealthStr = JSON.stringify(next.health || null);
655	  if (prevHealthStr !== nextHealthStr) {
656	    markData('health', prev.health, next.health);
657	  }
658	
659	  // ── last_updated ────────────────────────────────────────────────────
660	  if (prev.last_updated !== next.last_updated) {
661	    markData('last_updated', prev.last_updated, next.last_updated);
662	  }
663	
664	  return { type: changeType, changes: changes };
665	}
