667	/* ----------------------------------------------------------
668	   4c-iv. Combined Poll Function
669	   Fetches project data and work-package overview each cycle,
670	   compares against the previous snapshot, and either patches
671	   the DOM in-place (data-only changes) or triggers a full
672	   re-render (structural changes).
673	
674	   Parameters:
675	     app           — root element passed to renderProjectDetail
676	     repo          — repository name
677	     slug          — project slug
678	     pollStateRef  — single-element array [snapshot] so the poll
679	                     function can read and write the last state
680	                     without a module-scoped variable
681	     pollController — the owning pollController object; used to
682	                     call stopPolling() before a structural
683	                     re-render so no competing interval remains
684	   ---------------------------------------------------------- */
685	/**
686	 * @param {Element}  app
687	 * @param {string}   repo
688	 * @param {string}   slug
689	 * @param {Array}    pollStateRef  — [lastSnapshot]; mutated in place
690	 * @param {object}   pollController
691	 */
692	function _pollProjectDetail(app, repo, slug, pollStateRef, pollController) {
693	  // Guard: skip DOM patching when a modal is open or inline edit is active.
